async function compose(scenario: string): Promise<any> {
  const process = Bun.spawn(["python", "-c", PYTHON_DRIVER, resolve(ROOT, COMPOSER), scenario], { cwd: ROOT, stdout: "pipe", stderr: "pipe" })
  const [stdout, stderr, exitCode] = await Promise.all([new Response(process.stdout).text(), new Response(process.stderr).text(), process.exited])
  if (exitCode !== 0) throw new Error(`synthetic composer harness failed (${exitCode}): ${stderr}`)
  const line = stdout.trim().split(/\r?\n/).at(-1)
  if (!line) throw new Error("synthetic composer harness returned no result")
  return JSON.parse(line)
}

describe("M80 normalized composer v4 integration boundary", () => {
  test("snapshot and live composer bytes match the frozen root candidate", async () => {
    const [snapshotBytes, composerBytes] = await Promise.all([readFile(resolve(ROOT, SNAPSHOT)), readFile(resolve(ROOT, COMPOSER))])
    expect(m80HostedSha256(snapshotBytes)).toBe(SNAPSHOT_SHA256)
    expect(m80HostedSha256(composerBytes)).toBe(COMPOSER_SHA256)
    const snapshot = JSON.parse(snapshotBytes.toString("utf8"))
    const artifact = snapshot.artifacts.find((item: any) => item.path === COMPOSER)
    expect(artifact.sha256).toBe(COMPOSER_SHA256)
    expect(artifact.text).toBe(composerBytes.toString("utf8"))
    expect(snapshot.status).toBe("unaccepted")
  })

  test("actual composer mapping produces exact synthetic receipts accepted by preparation v3", async () => {
    const composed = await compose("valid")
    expect(composed.fixtureClassification).toBe("synthetic_no_authority")
    if (composed.rejected) throw new Error(JSON.stringify(composed))
    expect(composed.rejected).toBe(false)
    const checked: string[] = []
    const plan = await buildM80HostedPreparationPlan(composed.input, {
      now: new Date(composed.now),
      verifyPin: async pin => { checked.push(pin.path) },
      loadJsonEvidence: async pin => composed.evidence[pin.path],
    })
    expect(plan.profile).toBe(M80_HOSTED_PREPARATION_PROFILE)
    expect(composed.input.profile).toBe(M80_HOSTED_INPUT_PROFILE)
    expect(checked).toHaveLength(12)
    expect(plan.rehearsal).toMatchObject({ normalizedMetadataExact: true, applicationMetadataEquivalent: true, rawMetadataHashesEqual: false })
    expect(plan.executionAuthorized).toBe(false)
    expect(plan.noNetworkOrHostedActionPerformed).toBe(true)
  })

  test("composer refuses proof, archive, chronology, database, raw-state and legacy-profile contradictions", async () => {
    for (const scenario of ["wrong_proof_pin", "mismatched_backup", "mismatched_time", "mismatched_database", "raw_hash", "legacy_profile"]) {
      const result = await compose(scenario)
      expect(result).toMatchObject({ fixtureClassification: "synthetic_no_authority", scenario, rejected: true })
    }
  })

  test("composer refuses changed owner, target and current-publication observations", async () => {
    for (const scenario of ["owner", "target", "current_publication"]) {
      const result = await compose(scenario)
      expect(result).toMatchObject({ fixtureClassification: "synthetic_no_authority", scenario, rejected: true })
    }
  })
})
